def _split_reference(reference: str, default_section: str) -> tuple[str, str]:
    """Split the text between ``${`` and ``}`` into a section and key."""
    if ":" in reference:
        section, key = reference.split(":", 1)
        return section.strip(), key.strip().lower()
    return default_section, reference.strip().lower()


def parse(text: str) -> dict[str, dict[str, str]]:
    """Parse INI text."""
    sections: dict[str, dict[str, str]] = {}
    section_name = None
    continued_key = None

    for lineno, raw_line in enumerate(text.splitlines(), 1):
        stripped = raw_line.strip()

        # Blank lines and comments are ignored, and they end a continuation.
        if not stripped or stripped[0] in "#;":
            continued_key = None
            continue

        # An indented line continues the value last set, if there is one.
        if raw_line[0].isspace() and continued_key is not None:
            sections[section_name][continued_key] += "\n" + stripped
            continue

        continued_key = None
        line = stripped

        if line.startswith("[") and line.endswith("]"):
            section_name = line[1:-1].strip()
            sections.setdefault(section_name, {})
            continue

        equals = line.find("=")
        colon = line.find(":")
        if equals == -1:
            split_at = colon
        elif colon == -1:
            split_at = equals
        else:
            split_at = min(equals, colon)

        if split_at == -1:
            raise ParseError(lineno, "unrecognized line")

        key = line[:split_at].strip().lower()
        value = line[split_at + 1 :].strip()

        if section_name is None:
            raise ParseError(lineno, "key before any section")
        if not key:
            raise ParseError(lineno, "empty key")

        sections[section_name][key] = value
        continued_key = key

    values = {name: dict(keys) for name, keys in sections.items()}
    resolved: dict[tuple[str, str], str] = {}

    def expand(raw: str, section: str, stack: tuple[tuple[str, str], ...]) -> str:
        """Interpolate one raw value, leaving literal dollars alone."""
        pieces: list[str] = []
        index = 0
        length = len(raw)

        while index < length:
            char = raw[index]

            if char != "$":
                pieces.append(char)
                index += 1
                continue

            # "$$" is a literal dollar sign, and the result is not rescanned.
            if index + 1 < length and raw[index + 1] == "$":
                pieces.append("$")
                index += 2
                continue

            if index + 1 < length and raw[index + 1] == "{":
                end = raw.find("}", index + 2)
                if end != -1:
                    reference = raw[index + 2 : end]
                    ref_section, ref_key = _split_reference(reference, section)
                    pieces.append(resolve(ref_section, ref_key, stack))
                    index = end + 1
                    continue

            # Any other "$" (including an unterminated "${") is literal.
            pieces.append("$")
            index += 1

        return "".join(pieces)

    def resolve(
        section: str, key: str, stack: tuple[tuple[str, str], ...]
    ) -> str:
        """Return the fully interpolated value of one key."""
        identifier = (section, key)

        if identifier in resolved:
            return resolved[identifier]
        if identifier in stack:
            raise InterpolationError(
                f"circular reference to key {key!r} in section {section!r}"
            )
        if section not in values:
            raise InterpolationError(f"missing section {section!r}")
        if key not in values[section]:
            raise InterpolationError(
                f"missing key {key!r} in section {section!r}"
            )

        result = expand(values[section][key], section, stack + (identifier,))
        resolved[identifier] = result
        return result

    return {
        name: {key: resolve(name, key, ()) for key in keys}
        for name, keys in values.items()
    }

